diff --git a/evaluation/attribution/collect-artifacts.test.mjs b/evaluation/attribution/collect-artifacts.test.mjs
new file mode 100644
index 0000000..453f25a
--- /dev/null
+++ b/evaluation/attribution/collect-artifacts.test.mjs
@@ -0,0 +1,62 @@
+/**
+ * Regression: the collector must read the exit status out of a *real* CodeBuddy
+ * Bash result.
+ *
+ * The envelope is stable and labels its sections with initials: a real capture
+ * looks like
+ *
+ *   Command: node --test
+ *   Stdout: …
+ *   Stderr: (empty)
+ *   Exit Code: 0
+ *   Signal: (none)
+ *
+ * — note `Exit Code`, capital C. The reader used to match only the lowercase
+ * `Exit code:` spelling, which is what hand-written fixtures happened to use.
+ * So in a real run `exit_code` was always null and the downstream logic that
+ * classifies a failed call by its exit status never saw a failure. These cases
+ * pin the real spelling, and pin that it still reaches the collected operation.
+ */
+import test from "node:test";
+import assert from "node:assert/strict";
+
+import { collectArtifacts, outcomeOf } from "./collect-artifacts.mjs";
+
+/** One assistant Bash call and its result, in the real captured shape. */
+function capture(resultText) {
+  return [{
+    event: "http.request",
+    requestId: "req-1",
+    timestamp: "2026-09-04T13:30:00Z",
+    headers: { "x-conversation-id": "conv-1" },
+    body: {
+      json: {
+        messages: [
+          {
+            role: "assistant",
+            tool_calls: [{ id: "c1", function: { name: "Bash", arguments: '{"command":"node --test"}' } }],
+          },
+          { role: "tool", tool_call_id: "c1", content: resultText },
+        ],
+      },
+    },
+  }];
+}
+
+test("outcomeOf reads the capitalised `Exit Code` a real result carries", () => {
+  assert.equal(outcomeOf("Command: x\nStdout: hi\nStderr: (empty)\nExit Code: 0\nSignal: (none)").exit_code, 0);
+  assert.equal(outcomeOf("Command: x\nStdout: \nStderr: timed out\nExit Code: 28\nSignal: (none)").exit_code, 28);
+});
+
+test("the older lowercase spelling still reads, and no status is still null", () => {
+  assert.equal(outcomeOf("Exit code: 0").exit_code, 0);
+  assert.equal(outcomeOf("Stdout: hi, no status section").exit_code, null);
+});
+
+test("a captured operation carries the exit status into its result", () => {
+  const ok = collectArtifacts({ captureEvents: capture("Command: node --test\nStdout: pass\nStderr: (empty)\nExit Code: 0\nSignal: (none)") });
+  const failed = collectArtifacts({ captureEvents: capture("Command: node --test\nStdout: \nStderr: fail\nExit Code: 1\nSignal: (none)") });
+
+  assert.equal(ok[0].operations[0].result.exit_code, 0);
+  assert.equal(failed[0].operations[0].result.exit_code, 1);
+});

delivered_content.text:
  1→/**
  2→ * Artifact collection — the places where a discriminative token could land.
  3→ *
  4→ * A token found "somewhere in the run" cannot support a `used` claim. What is
  5→ * needed is a specific operation: this tool call, at this point in the session,
  6→ * with this result. So everything collected here carries three things:
  7→ *
  8→ *   message_index  where it sits in the session's message sequence. This is what
  9→ *                  ordering is judged on, and it is not the same as time: a
 10→ *                  model can emit several tool calls in one message, so two
 11→ *                  calls share a timestamp while the second was written before
 12→ *                  the first one's result existed. Using the timestamp there
 13→ *                  reads "the content arrived at 10:01 and the call is stamped
 14→ *                  10:01" as influence, when the model had not seen a thing.
 15→ *   seq            position among this session's calls, for display.
 16→ *   call_id      which result belongs to which call. A command and its output
 17→ *                must stay attached: the command carries what was asked for and
 18→ *                the output carries what came back, and the two answer different
 19→ *                questions.
 20→ *   locus        where to look to see it again — request id, message index,
 21→ *                call id, or file and hunk. An event whose evidence cannot be
 22→ *                reopened is an assertion, not a record.
 23→ *
 24→ * `occurred_at` is the timestamp of the earliest captured request that carried
 25→ * the message. Messages accumulate across turns, so the last request holds them
 26→ * all; the first one to contain a message is when it happened.
 27→ *
 28→ * A diff hunk has no position at all. A diff is the end state of a run, not an
 29→ * event within it, so it gets `message_index: null` and `ordering:
 30→ * "end_of_run"` — and "after everything" is *not* good enough to establish that
 31→ * an asset was read first. A run that edits a file and then reads the asset
 32→ * leaves the same diff as one that reads first and then edits. The judge
 33→ * therefore refuses to promote on a diff hunk alone; the edit operation that
 34→ * produced the change is what carries a position, and that is what gets judged.
 35→ *
 36→ * Usage:
 37→ *   node evaluation/attribution/collect-artifacts.mjs <capture.jsonl ...> \
 38→ *     [--task=<task.md>] [--diff=<file.diff>] [--pre=<path>=<file> ...] [--json]
 39→ */
 40→
 41→import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
 42→import { dirname } from "node:path";
 43→import {
 44→  normalizeSessionKey,
 45→  parseJsonl,
 46→  splitCommandAndOutput,
 47→  commandEndpoint,
 48→  isListingAction,
 49→} from "../provenance/build-events.mjs";
 50→
 51→/** Commands that run a check rather than change something. */
 52→const TEST_COMMAND = /\b(npm|pnpm|yarn)\s+(run\s+)?test\b|\bnode\s+--test\b|\bpytest\b|\bgo\s+test\b|\bcargo\s+test\b|\bvitest\b|\bjest\b|verify[\w-]*\.sh\b/;
 53→
 54→function textOf(content) {
 55→  return typeof content === "string" ? content : JSON.stringify(content ?? "");
 56→}
 57→
 58→/** Tool results in one captured request, each with the message index it sat at. */
 59→function toolResults(body) {
 60→  const out = [];
 61→  const msgs = Array.isArray(body?.messages) ? body.messages : [];
 62→  msgs.forEach((message, index) => {
 63→    if (message?.role === "tool") out.push({ index, text: textOf(message.content) });
 64→    for (const block of Array.isArray(message?.content) ? message.content : []) {
 65→      if (block?.type === "tool_result") out.push({ index, text: textOf(block.content) });
 66→    }
 67→  });
 68→  return out;
 69→}
 70→
 71→/**
 72→ * Walk one captured request's messages, emitting a record per tool call and per
 73→ * tool result, in message order.
 74→ */
 75→function messagesOf(body) {
 76→  const out = [];
 77→  const msgs = Array.isArray(body?.messages) ? body.messages : [];
 78→  msgs.forEach((message, index) => {
 79→    if (Array.isArray(message?.tool_calls)) {
 80→      for (const tc of message.tool_calls) {
 81→        out.push({
 82→          index,
 83→          role: "call",
 84→          call_id: String(tc?.id ?? ""),
 85→          tool_name: String(tc?.function?.name ?? tc?.name ?? ""),
 86→          text: String(tc?.function?.arguments ?? JSON.stringify(tc?.input ?? "")),
 87→        });
 88→      }
 89→    }
 90→    // Anthropic-shaped blocks carry tool_use / tool_result inside content.
 91→    const blocks = Array.isArray(message?.content) ? message.content : [];
 92→    for (const block of blocks) {
 93→      if (block?.type === "tool_use") {
 94→        out.push({
 95→          index, role: "call",
 96→          call_id: String(block.id ?? ""),
 97→          tool_name: String(block.name ?? ""),
 98→          text: JSON.stringify(block.input ?? ""),
 99→        });
100→      } else if (block?.type === "tool_result") {
101→        out.push({
102→          index, role: "result",
103→          call_id: String(block.tool_use_id ?? ""),
104→          tool_name: "",
105→          text: textOf(block.content),
106→        });
107→      }
108→    }
109→    if (message?.role === "tool") {
110→      out.push({
111→        index, role: "result",
112→        call_id: String(message.tool_call_id ?? ""),
113→        tool_name: "",
114→        text: textOf(message.content),
115→      });
116→    }
117→  });
118→  return out;
119→}
120→
121→/** Exit status and stderr, read out of a shell tool result envelope. */
122→export function outcomeOf(resultText) {
123→  const s = String(resultText ?? "");
124→  const code = /(?:^|\n)Exit code:\s*(\d+)/.exec(s);
125→  const stderr = /(?:^|\n)Stderr:\s*([\s\S]*)$/.exec(s);
126→  return {
127→    exit_code: code ? Number(code[1]) : null,
128→    stderr: stderr ? stderr[1].trim().slice(0, 400) : "",
129→  };
130→}
131→
132→/**
133→ * Split a unified diff into hunks, each keeping the file and line range it
134→ * touches — "the token is in the diff" is not a location, "the token is in
135→ * src/proxy.ts lines 40-58" is.
136→ */
137→export function diffHunks(diffText) {
138→  const hunks = [];
139→  let file = "";
140→  let current = null;
141→  for (const line of String(diffText ?? "").split("\n")) {
142→    const plus = /^\+\+\+ [ab]\/(.+)$/.exec(line);
143→    if (plus) { file = plus[1]; current = null; continue; }
144→    const at = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/.exec(line);
145→    if (at) {
146→      current = {
147→        file,
148→        start: Number(at[1]),
149→        end: Number(at[1]) + (at[2] ? Number(at[2]) : 1) - 1,
150→        lines: [],
151→      };
152→      hunks.push(current);
153→      continue;
154→    }
155→    if (current && /^[+ -]/.test(line)) current.lines.push(line);
156→  }
157→  return hunks.map((h) => ({ ...h, text: h.lines.join("\n") }));
158→}
159→
160→/**
161→ * Collect every operation in a run, ordered, with calls and results paired.
162→ *
163→ * Messages repeat across turns as the conversation grows. A call is recorded
164→ * once, at the turn it first appeared, so the sequence reflects when things
165→ * happened rather than how many times they were re-sent.
166→ */
167→export function collectArtifacts({ captureEvents = [], taskDescription = "", preChangeFiles = {}, diff = "", runId = null, taskId = null }) {
168→  const bySession = new Map();
169→
170→  const requests = captureEvents
171→    .filter((e) => e?.event === "http.request" && Array.isArray(e?.body?.json?.messages))
172→    .sort((a, b) => String(a.timestamp ?? "").localeCompare(String(b.timestamp ?? "")));
173→
174→  for (const event of requests) {
175→    const sessionKey = normalizeSessionKey(
176→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
177→    );
178→    if (!bySession.has(sessionKey)) bySession.set(sessionKey, { calls: new Map(), results: new Map() });
179→    const store = bySession.get(sessionKey);
180→    const requestId = String(event.requestId ?? "");
181→    const timestamp = String(event.timestamp ?? "");
182→
183→    for (const m of messagesOf(event.body.json)) {
184→      // Key on the call id where there is one. Without it a message can still
185→      // be identified by where it sits, which is stable across turns because
186→      // messages are only ever appended.
187→      const key = m.call_id || `${m.role}@${m.index}`;
188→      const target = m.role === "call" ? store.calls : store.results;
189→      if (target.has(key)) continue; // already seen in an earlier turn
190→      target.set(key, {
191→        ...m,
192→        first_seen_at: timestamp,
193→        locus: `request(${requestId}):msg[${m.index}]${m.call_id ? `:${m.call_id}` : ""}`,
194→      });
195→    }
196→  }
197→
198→  // What the model was *offered* without fetching: the body of every search /
199→  // list result. A discriminative token that appears in one of these reached
200→  // the model as a snippet, not through a full-content read — so a later use of
201→  // it cannot be told apart from having read the snippet. Kept with the message
202→  // index it arrived at, so the judge can screen only what preceded an
203→  // operation. Confirmed necessary by the real run: `47318` came back in 13
204→  // search snippets while `10.244.7.19` came back in none.
205→  // Every tool result's output, not only search results. The first real run
206→  // showed why the narrower version is not enough: the consumer's own
207→  // auto-extracted skill was read at message 4, before any of the credited
208→  // assets. It happened not to carry the discriminative tokens that time —
209→  // but a token delivered by *any* earlier result (another asset's body, a
210→  // file read, a search snippet) means its later use cannot be credited to
211→  // the fetch the judge is looking at. So the judge is given everything that
212→  // arrived, with where it came from, and decides by earliest delivery.
213→  const deliveredBySession = new Map();
214→  for (const event of requests) {
215→    const sessionKey = normalizeSessionKey(
216→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
217→    );
218→    for (const { index, text } of toolResults(event.body.json)) {
219→      const { command, output } = splitCommandAndOutput(text);
220→      if (!output) continue;
221→      const endpoint = commandEndpoint(command);
222→      if (!deliveredBySession.has(sessionKey)) deliveredBySession.set(sessionKey, new Map());
223→      const byIndex = deliveredBySession.get(sessionKey);
224→      // First arrival of a given result is when it was delivered.
225→      if (!byIndex.has(index)) {
226→        byIndex.set(index, {
227→          message_index: index,
228→          endpoint: endpoint || null,
229→          kind: endpoint ? (isListingAction(endpoint) ? "listing" : "fetch") : "other",
230→          // Enough of the command to name the source in a judgement; not the
231→          // full text, which can be long and carries nothing the locus lacks.
232→          source: String(command ?? "").trim().split("\n")[0].slice(0, 160),
233→          text: output,
234→        });
235→      }
236→    }
237→  }
238→  const offeredBySession = new Map();
239→  for (const [sessionKey, byIndex] of deliveredBySession) {
240→    const listings = new Map();
241→    for (const [i, d] of byIndex) if (d.kind === "listing") listings.set(i, d);
242→    offeredBySession.set(sessionKey, listings);
243→  }
244→
245→  const sessions = [];
246→  for (const [sessionKey, store] of bySession) {
247→    const operations = [];
248→    const ordered = [...store.calls.values()].sort((a, b) => a.index - b.index);
249→
250→    ordered.forEach((call, seq) => {
251→      const result = store.results.get(call.call_id) ?? null;
252→      const { command, output } = splitCommandAndOutput(result?.text ?? "");
253→      operations.push({
254→        seq,
255→        kind: TEST_COMMAND.test(call.text) ? "test_command" : "tool_call",
256→        // The position the model wrote this call at. Ordering is judged on it,
257→        // never on the timestamp — see the note at the top of this file.
258→        message_index: call.index,
259→        occurred_at: call.first_seen_at || null,
260→        ordering: "observed",
261→        call_id: call.call_id,
262→        tool_name: call.tool_name,
263→        locus: `${call.locus}:arguments`,
264→        // The arguments are where a token the model *acted on* appears — in the
265→        // mainline scenario the bridge address is inside the curl command here,
266→        // not in anything that came back.
267→        text: call.text,
268→        result: result
269→          ? {
270→              message_index: result.index,
271→              locus: result.locus,
272→              // Kept apart deliberately: the echoed command says what was asked
273→              // for and the output says what came back. Scanning them as one
274→              // blob is how a call that timed out with empty output still
275→              // matched every pattern in its own command.
276→              command_echo: command,
277→              output,
278→              ...outcomeOf(result.text),
279→            }
280→          : null,
281→      });
282→    });
283→
284→    // A diff has no time of its own; it is what the run left behind.
285→    diffHunks(diff).forEach((h, i) => {
286→      operations.push({
287→        seq: operations.length + i,
288→        kind: "diff_hunk",
289→        // No position and no time. "After everything" cannot show the asset was
290→        // read before the edit, because a run that edited first and read after
291→        // leaves exactly this diff.
292→        message_index: null,
293→        occurred_at: null,
294→        ordering: "end_of_run",
295→        call_id: "",
296→        tool_name: "",
297→        locus: `diff:${h.file}:${h.start}-${h.end}`,
298→        text: h.text,
299→        result: null,
300→      });
301→    });
302→
303→    sessions.push({
304→      session_key: sessionKey,
305→      // Stamped by the runner so the judge's events carry them; null when the
306→      // artifacts were collected outside a run. Generalisation is counted as
307→      // distinct task ids, so a missing task id is a missing signal, not zero.
308→      run_id: runId,
309→      task_id: taskId,
310→      task_description: taskDescription,
311→      pre_change_files: preChangeFiles,
312→      diff,
313→      offered_content: [...(offeredBySession.get(sessionKey)?.values() ?? [])]
314→        .sort((a, b) => a.message_index - b.message_index),
315→      // Everything that came back from any tool, in arrival order. The judge
316→      // credits a token to a fetch only when that fetch is the token's
317→      // earliest delivery; anything earlier — another asset's body, a file
318→      // read, a snippet — means the credit cannot be given.
319→      delivered_content: [...(deliveredBySession.get(sessionKey)?.values() ?? [])]
320→        .sort((a, b) => a.message_index - b.message_index),
321→      operations,
322→      test_commands: operations.filter((o) => o.kind === "test_command").map((o) => o.locus),
323→      tool_call_args: operations.filter((o) => o.kind !== "diff_hunk").map((o) => o.text),
324→    });
325→  }
326→  return sessions;
327→}
328→
329→export function renderArtifacts(sessions) {
330→  const lines = ["# Collected artifacts", ""];
331→  if (sessions.length === 0) {
332→    lines.push("No session in the capture carried a tool call. Nothing to attribute against —");
333→    lines.push("**not** an empty result meaning nothing was used.");
334→    return lines.join("\n");
335→  }
336→  for (const s of sessions) {
337→    lines.push(`## ${s.session_key || "(no conversation id)"}`, "");
338→    lines.push(`  ${s.operations.length} operation(s), ${s.test_commands.length} of them checks`);
339→    lines.push(`  task description: ${s.task_description ? `${s.task_description.length} chars` : "not supplied"}`);
340→    lines.push(`  pre-change files: ${Object.keys(s.pre_change_files).length}`);
341→    lines.push("");
342→    for (const op of s.operations.slice(0, 25)) {
343→      const when = op.message_index == null ? op.ordering : `msg[${op.message_index}]`;
344→      const outcome = op.result
345→        ? (op.result.exit_code === null ? "" : ` exit=${op.result.exit_code}`)
346→        : " (no result)";
347→      lines.push(`  [${String(op.seq).padStart(2)}] ${op.kind.padEnd(12)} ${when}  ${op.tool_name || "-"}${outcome}`);
348→      lines.push(`       ${op.locus}`);
349→    }
350→    if (s.operations.length > 25) lines.push(`  … ${s.operations.length - 25} more`);
351→    lines.push("");
352→  }
353→  return lines.join("\n");
354→}
355→
356→// ── CLI ───────────────────────────────────────────────────────────
357→if (import.meta.url === `file://${process.argv[1]}`) {
358→  const args = process.argv.slice(2);
359→  const flag = (n) => args.filter((a) => a.startsWith(`--${n}=`)).map((a) => a.slice(n.length + 3));
360→  const capturePaths = args.filter((a) => !a.startsWith("--"));
361→  if (capturePaths.length === 0) {
362→    console.error("usage: node collect-artifacts.mjs <capture.jsonl ...> [--task=f] [--diff=f] [--pre=path=file] [--json]");
363→    process.exit(2);
364→  }
365→
366→  const preChangeFiles = {};
367→  for (const spec of flag("pre")) {
368→    const at = spec.indexOf("=");
369→    if (at < 0) { console.error(`--pre expects <path>=<file>, got ${spec}`); process.exit(2); }
370→    preChangeFiles[spec.slice(0, at)] = readFileSync(spec.slice(at + 1), "utf8");
371→  }
372→
373→  const sessions = collectArtifacts({
374→    captureEvents: capturePaths.flatMap((p) => parseJsonl(readFileSync(p, "utf8"))),
375→    taskDescription: flag("task").map((p) => readFileSync(p, "utf8")).join("\n"),
376→    diff: flag("diff").map((p) => readFileSync(p, "utf8")).join("\n"),
377→    preChangeFiles,
378→    runId: flag("run-id")[0] || null,
379→    taskId: flag("task-id")[0] || null,
380→  });
381→
382→  const outPath = "evaluation/attribution/artifacts/run-artifacts.json";
383→  mkdirSync(dirname(outPath), { recursive: true });
384→  writeFileSync(outPath, JSON.stringify(sessions, null, 2), "utf8");
385→
386→  if (args.includes("--json")) console.log(JSON.stringify(sessions, null, 2));
387→  else console.log(renderArtifacts(sessions), `\nWritten to ${outPath}`);
388→}
389→

  1→/**
  2→ * Provenance event builder — puts "who wrote it" and "who used it" on one record.
  3→ *
  4→ * The existing telemetry is missing that edge. `tool_call_logs` records only the
  5→ * consumer (user_id / agent_id); the asset's owner lives in the asset record, and
  6→ * the two were never joined. Without the edge neither the team dimension nor
  7→ * author confidence can be computed — and it cannot be backfilled later, because
  8→ * asset ownership changes and versions roll forward, so a lookup after the fact
  9→ * returns a different row than the one that was actually used.
 10→ *
 11→ * Each of the three inputs answers only part of the question:
 12→ *
 13→ *   asset pool snapshot   who wrote it, when, which version
 14→ *   tool_call_logs        who used it, whether the call succeeded
 15→ *                         (written by the service itself; the model cannot alter it)
 16→ *   capture JSONL         which asset ids came back in the response
 17→ *
 18→ * That last one is the crux: a `skill/search` bridge row records the request only,
 19→ * so it holds the query but not what was returned. Asset identity can therefore be
 20→ * recovered only from the captured response. Each event records how the fetch was
 21→ * witnessed in `observation`:
 22→ *
 23→ *   bridge+wire   service-side success record AND an asset id parsed from the
 24→ *                 capture (strongest)
 25→ *   bridge_only   service-side success, but the capture missed it — only the
 26→ *                 channel is known
 27→ *   wire_only     an asset id in the capture with no matching service-side
 28→ *                 success record (doubtful)
 29→ *
 30→ * Usage:
 31→ *   node evaluation/provenance/build-events.mjs \
 32→ *     evaluation/provenance/artifacts/asset-pool-snapshot.json \
 33→ *     evaluation/gate0/artifacts/tool-call-logs.jsonl \
 34→ *     [capture.jsonl ...]
 35→ */
 36→
 37→import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
 38→import { createHash } from "node:crypto";
 39→import { dirname } from "node:path";
 40→
 41→/**
 42→ * Stable event id, referenced by gate decisions (`evidence_refs`) and receipts.
 43→ * Derived from content rather than generated randomly, so re-running over the
 44→ * same input yields the same ids and the two sides can be reconciled.
 45→ */
 46→export function eventId(parts) {
 47→  const digest = createHash("sha1").update(parts.join("|")).digest("hex");
 48→  return `evt-${digest.slice(0, 12)}`;
 49→}
 50→
 51→/** Relation between consumer and producer. Only cross_user is team value. */
 52→export function classifyRelation(producer, actor) {
 53→  const pu = producer.user_id || "";
 54→  const pa = producer.agent_id || "";
 55→  const au = actor.user_id || "";
 56→  const aa = actor.agent_id || "";
 57→
 58→  // If either identity is missing the relation is undecidable. Report unknown
 59→  // rather than defaulting to self — defaulting would quietly erase genuine
 60→  // cross-person use.
 61→  if (!pu || !au) return "unknown";
 62→  if (pu !== au) return "cross_user";
 63→  if (pa && aa && pa !== aa) return "cross_agent";
 64→  return "self";
 65→}
 66→
 67→/**
 68→ * The proxy prefixes session_key with the client name (codebuddy:xxx) while the
 69→ * knowledge service stores the bare x-conversation-id. Normalise before joining.
 70→ */
 71→export function normalizeSessionKey(key) {
 72→  const s = String(key ?? "");
 73→  const idx = s.indexOf(":");
 74→  return idx >= 0 ? s.slice(idx + 1) : s;
 75→}
 76→
 77→/** Parse JSONL line by line, skipping malformed lines instead of failing whole. */
 78→export function parseJsonl(text) {
 79→  const rows = [];
 80→  for (const line of String(text).split("\n")) {
 81→    if (!line.trim()) continue;
 82→    try { rows.push(JSON.parse(line)); } catch { /* skip malformed line */ }
 83→  }
 84→  return rows;
 85→}
 86→
 87→/**
 88→ * Split a Bash tool result into the command that was issued and the output it
 89→ * produced.
 90→ *
 91→ * These must never be scanned as one blob. A tool result echoes the command
 92→ * before its output, so a call that timed out after 75 s with empty stdout
 93→ * still contains the bridge URL and the asset name — matching the whole thing
 94→ * reads the *request* as if it were the response. The endpoint is read from the
 95→ * command, which is what the command is for; the payload only from the output.
 96→ */
 97→export function splitCommandAndOutput(text) {
 98→  const s = String(text ?? "");
 99→  const i = s.search(/(^|\n)Stdout:/);
100→  // No envelope — a native tool result rather than a shell call. The two halves
101→  // cannot be separated, so the whole thing is treated as output and the
102→  // command as absent. That keeps the id visible while making targeting
103→  // undecidable, which is the honest reading: with no command to inspect,
104→  // nothing here can establish that this asset was the one asked for.
105→  if (i < 0) return { command: "", output: s };
106→  const nl = s.indexOf("Stdout:", i);
107→  return { command: s.slice(0, i), output: s.slice(nl + "Stdout:".length) };
108→}
109→
110→/**
111→ * The action a command invoked, as `skill:search`, or "" if not one.
112→ *
113→ * The knowledge service is not shaped like the other two. It runs on its own
114→ * port and takes the operation in the body (`tool_name`) rather than in the
115→ * path, so a path-only pattern does not see it at all — and an unrecognised
116→ * command means the response is never inspected, which shows up as "delivery
117→ * unknown" for a channel where delivery is perfectly knowable.
118→ */
119→export function commandEndpoint(command) {
120→  const cmd = String(command ?? "");
121→  const bridge = /https?:\/\/[^\s'"]*\/(skill|memory)-bridge\/v3\/[a-z]+\/([a-z/-]+)/.exec(cmd);
122→  if (bridge) return `${bridge[1]}:${bridge[2].replace(/\/+$/, "")}`;
123→
124→  if (/https?:\/\/[^\s'"]*\/v3\/tools\/call/.test(cmd)) {
125→    const tool = /"tool_name"\s*:\s*"([^"]+)"/.exec(cmd);
126→    return `knowledge:${tool ? tool[1] : "call"}`;
127→  }
128→  if (/https?:\/\/[^\s'"]*\/v3\/tools\/list/.test(cmd)) return "knowledge:list";
129→  return "";
130→}
131→
132→/** Enumeration endpoints hand back a list; they never retrieve one asset. */
133→export function isListingAction(action) {
134→  return /^(search|list|listing|list_[a-z_]+|search_[a-z_]+)$/.test(String(action ?? "").split(":").pop() ?? "");
135→}
136→
137→/**
138→ * Did this command ask for *this* asset's content?
139→ *
140→ * The distinction that the whole `fetched` state rests on: appearing in a
141→ * `skill/search` result means the asset was **offered**, and appearing in a
142→ * `get-by-name` response means it was **retrieved**. Only the second is a fetch.
143→ */
144→export function commandTargetsAsset(command, asset) {
145→  const cmd = String(command ?? "");
146→  const endpoint = commandEndpoint(cmd);
147→  if (!endpoint || isListingAction(endpoint)) return false;
148→  const id = String(asset?.asset_id ?? "");
149→  const name = String(asset?.name ?? "");
150→  if (id && cmd.includes(id)) return true;
151→  if (name && new RegExp(`"(name|skill_name)"\\s*:\\s*"${escapeRegExp(name)}"`).test(cmd)) return true;
152→  return false;
153→}
154→
155→/**
156→ * What a bridge response actually handed back for this asset.
157→ *
158→ * A non-enumeration endpoint is not enough to say the body arrived. `get` with
159→ * `include_content:false` answers with id, name and version; `update` answers
160→ * with a metadata summary. Both name the asset, both come from an endpoint that
161→ * is not a listing, and neither delivers a single line of the asset's content —
162→ * so an endpoint allow-list would pass all of them.
163→ *
164→ * The version is read from the same place for the same reason: the response
165→ * states which revision it returned, and that is the only source entitled to
166→ * say so. The snapshot's version describes the pool now, not what came back.
167→ *
168→ * Returns `{ delivered, version }` where `delivered` is null when the payload
169→ * could not be parsed at all — unknown, which is not false.
170→ */
171→export function inspectDelivery(output, assetId) {
172→  const envelope = firstJsonObject(output);
173→  if (!envelope) return { delivered: null, version: null };
174→
175→  // An explicit refusal — the envelope's own non-zero code (40301 not
176→  // visible, 40401 not found, 40302 write disabled …) — is a known
177→  // non-delivery, not an unknown one. Nothing of the asset came back, and a
178→  // later stage must not read "fetched" into it (found on the second
179→  // scenario's first preparation run, where every get was refused and the
180→  // receipt would have said 已取回).
181→  if (typeof envelope.code === "number" && envelope.code !== 0) {
182→    return { delivered: false, version: null, refused: envelope.code };
183→  }
184→
185→  // The asset may be the whole payload or one item inside a list.
186→  const data = envelope.data ?? envelope;
187→  const candidates = [data, ...(Array.isArray(data?.items) ? data.items : [])];
188→  const record = candidates.find((c) => c && typeof c === "object"
189→    && [c.skill_id, c.wiki_id, c.asset_id, c.id].some((v) => String(v ?? "") === assetId));
190→  if (!record) return { delivered: null, version: null };
191→
192→  const body = [record.content, record.skill_md, record.body, record.text, record.markdown]
193→    .find((v) => typeof v === "string");
194→  const version = record.version ?? null;
195→
196→  // A field that exists but is empty is a delivery of nothing. The threshold is
197→  // deliberately low — one line of real content is content — but zero is zero.
198→  return { delivered: typeof body === "string" ? body.trim().length > 0 : false, version };
199→}
200→
201→/** First balanced JSON object in a blob of text. */
202→function firstJsonObject(text) {
203→  const s = String(text ?? "");
204→  const start = s.indexOf("{");
205→  if (start < 0) return null;
206→  let depth = 0, inStr = false, esc = false;
207→  for (let i = start; i < s.length; i += 1) {
208→    const ch = s[i];
209→    if (inStr) {
210→      if (esc) esc = false;
211→      else if (ch === "\\") esc = true;
212→      else if (ch === '"') inStr = false;
213→      continue;
214→    }
215→    if (ch === '"') inStr = true;
216→    else if (ch === "{") depth += 1;
217→    else if (ch === "}") {
218→      depth -= 1;
219→      if (depth === 0) { try { return JSON.parse(s.slice(start, i + 1)); } catch { return null; } }
220→    }
221→  }
222→  return null;
223→}
224→
225→/** Every tool result in a captured request, paired with its call id. */
226→function toolResultsOf(body) {
227→  const out = [];
228→  const msgs = Array.isArray(body?.messages) ? body.messages : [];
229→  msgs.forEach((message, index) => {
230→    if (message?.role === "tool") {
231→      const c = message.content;
232→      out.push({ index, callId: String(message.tool_call_id ?? ""), text: typeof c === "string" ? c : JSON.stringify(c ?? "") });
233→    }
234→    const blocks = Array.isArray(message?.content) ? message.content : [];
235→    for (const block of blocks) {
236→      if (block?.type !== "tool_result") continue;
237→      const c = block.content;
238→      out.push({ index, callId: String(block.tool_use_id ?? ""), text: typeof c === "string" ? c : JSON.stringify(c ?? "") });
239→    }
240→  });
241→  return out;
242→}
243→
244→/** Canonical form of a JSON blob, so two spellings of one body compare equal. */
245→/**
246→ * Keys the proxy adds to a request body on the way through. The model never
247→ * writes these; the bridge injects identity from the session (skill-bridge.ts:
248→ * user_id / team_id / agent_id, plus routing fields). So the service-side
249→ * `request_body` is the model's body *plus* these, and an exact-string compare
250→ * against what the model wrote never matches. That is what left A's two
251→ * get-by-name calls reporting wire_only with "no service row" when the rows
252→ * were right there.
253→ */
254→const PROXY_INJECTED_KEYS = new Set([
255→  "user_id", "team_id", "agent_id", "task_id", "space_id", "service_id",
256→]);
257→
258→/**
259→ * Canonical form of a request body for matching: parsed, keys sorted at every
260→ * depth, and the proxy-injected identity fields dropped from the top level.
261→ *
262→ * Dropping them is a defined normalisation, not a loosening — the fields that
263→ * distinguish one call from another (skill_id, skill_name, include_content)
264→ * are all kept, so two different requests still differ. Within one session the
265→ * identity is constant, so removing it cannot merge calls that were really
266→ * distinct.
267→ */
268→function canonicalRequest(text) {
269→  let obj;
270→  try { obj = JSON.parse(String(text ?? "")); } catch { return String(text ?? "").trim(); }
271→  const sort = (v) => {
272→    if (Array.isArray(v)) return v.map(sort);
273→    if (v && typeof v === "object") {
274→      const out = {};
275→      for (const k of Object.keys(v).sort()) out[k] = sort(v[k]);
276→      return out;
277→    }
278→    return v;
279→  };
280→  if (obj && typeof obj === "object" && !Array.isArray(obj)) {
281→    const kept = {};
282→    for (const k of Object.keys(obj)) if (!PROXY_INJECTED_KEYS.has(k)) kept[k] = obj[k];
283→    obj = kept;
284→  }
285→  return JSON.stringify(sort(obj));
286→}
287→
288→/** The `-d '…'` payload a curl command carried, for pairing with a service row. */
289→export function requestPayloadOf(command) {
290→  const m = /-d\s+'([\s\S]*?)'(?:\s|$)/.exec(String(command ?? ""))
291→    ?? /-d\s+"([\s\S]*?)"(?:\s|$)/.exec(String(command ?? ""));
292→  if (!m) return "";
293→  return canonicalRequest(m[1]);
294→}
295→
296→/**
297→ * Where each asset was seen in the capture, and — the part that matters —
298→ * whether the call that produced it had asked for that asset.
299→ *
300→ * Every targeted response is kept **separately**. Summarising them per asset
301→ * per session is what produced events assembled from different calls: a first
302→ * `get` with include_content:false supplying the version, a second `get` of a
303→ * different revision supplying the delivery flag and the entry position, and
304→ * the first call id supplying the evidence reference. Every field passed its
305→ * own check and the record as a whole described a retrieval that never
306→ * happened — and it validated against the contract, because the contract
307→ * constrains fields, not their provenance.
308→ *
309→ * So version, delivery, position and reference all come from one response, and
310→ * an asset read twice produces two events.
311→ *
312→ * Only tool *results* are searched: a request carries intent rather than
313→ * delivery. Within a result, the asset id must appear in the output half and
314→ * the targeting decision is made from the command half.
315→ */
316→export function extractAssetMentions(events, assets) {
317→  const mentions = new Map(); // assetId -> Map<sessionKey, {targeted, endpoints:Set, callIds:Set}>
318→  const list = [...assets].filter((a) => a?.asset_id);
319→  if (list.length === 0) return mentions;
320→  const known = new Set(list.map((a) => a.asset_id));
321→  // Targeted responses for assets the frozen snapshot does not hold. Iterating
322→  // the snapshot's assets makes these invisible, and invisible is the worst
323→  // outcome for exactly this case: an asset that appeared after the freeze —
324→  // the system auto-extracts skills from finished sessions — is the answer
325→  // leak the freeze exists to catch. The first real consumer run read such a
326→  // skill before any credited asset and no event recorded it.
327→  const unknown = new Map(); // asset_id -> {asset_id, name, version, sessions:Set, first_index}
328→
329→  for (const event of events) {
330→    if (event?.event !== "http.request") continue;
331→    const body = event?.body?.json;
332→    if (!body || !Array.isArray(body.messages)) continue;
333→
334→    const sessionKey = normalizeSessionKey(
335→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
336→    );
337→
338→    for (const { index, callId, text } of toolResultsOf(body)) {
339→      const { command, output } = splitCommandAndOutput(text);
340→      if (!output) continue;
341→
342→      // A non-listing response naming a skill id the snapshot lacks.
343→      const ep = commandEndpoint(command);
344→      if (ep && !isListingAction(ep)) {
345→        const env = firstJsonObject(output);
346→        const rec = env?.data && typeof env.data === "object" ? env.data : null;
347→        const rid = rec ? String(rec.skill_id ?? rec.wiki_id ?? rec.asset_id ?? "") : "";
348→        if (rid && !known.has(rid)) {
349→          if (!unknown.has(rid)) {
350→            unknown.set(rid, { asset_id: rid, name: String(rec.name ?? ""), version: rec.version ?? null, sessions: new Set(), first_index: index });
351→          }
352→          const u = unknown.get(rid);
353→          u.sessions.add(sessionKey);
354→          if (index < u.first_index) u.first_index = index;
355→        }
356→      }
357→
358→      for (const asset of list) {
359→        if (!output.includes(asset.asset_id)) continue;
360→        if (!mentions.has(asset.asset_id)) mentions.set(asset.asset_id, new Map());
361→        const bySession = mentions.get(asset.asset_id);
362→        if (!bySession.has(sessionKey)) {
363→          bySession.set(sessionKey, {
364→            endpoints: new Set(), offered: false, responses: [], seen: new Set(),
365→          });
366→        }
367→        const bucket = bySession.get(sessionKey);
368→        const endpoint = commandEndpoint(command);
369→        if (endpoint) bucket.endpoints.add(endpoint);
370→
371→        if (!commandTargetsAsset(command, asset)) { bucket.offered = true; continue; }
372→
373→        // Results repeat as the conversation grows; record each response once.
374→        const key = `${callId}|${index}`;
375→        if (bucket.seen.has(key)) continue;
376→        bucket.seen.add(key);
377→
378→        // One response, one record. The index is the message carrying the
379→        // *result*, not the call: a model can emit several calls in one
380→        // message, and the second was written before the first one's result
381→        // existed.
382→        const { delivered, version, refused = null } = inspectDelivery(output, asset.asset_id);
383→        bucket.responses.push({
384→          callId, endpoint, messageIndex: index, delivered, version, refused,
385→          requestPayload: requestPayloadOf(command),
386→        });
387→      }
388→    }
389→  }
390→  mentions.unknownAssets = [...unknown.values()].map((u) => ({ ...u, sessions: [...u.sessions] }));
391→  return mentions;
392→}
393→
394→
395→/**
396→ * Does this bridge call target the given asset specifically?
397→ *
398→ * The distinction that matters: `skill/search` returns a list, so an asset
399→ * appearing in its results was *offered*, not retrieved. Only a call that names
400→ * the asset — by id, or by the name the asset is registered under — is evidence
401→ * that its content was actually pulled into the session.
402→ *
403→ * Without this, any successful call in the session would mark every asset
404→ * mentioned anywhere in the capture as fetched, and that error would propagate
405→ * into the used judgement built on top of it.
406→ */
407→export function callTargetsAsset(call, asset) {
408→  const body = String(call.requestBody ?? "");
409→  if (!body) return false;
410→  const id = String(asset.asset_id ?? "");
411→  const name = String(asset.name ?? "");
412→
413→  // Listing endpoints enumerate; they never target one asset.
414→  const endpoint = String(call.executedEndpoint ?? "");
415→  if (/^(search|list|listing)$/.test(endpoint)) return false;
416→
417→  if (id && body.includes(id)) return true;
418→  // get-by-name and friends carry the registered name rather than the id.
419→  if (name && new RegExp(`"(name|skill_name)"\\s*:\\s*"${escapeRegExp(name)}"`).test(body)) return true;
420→  return false;
421→}
422→
423→function escapeRegExp(s) {
424→  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
425→}
426→
427→/** Combine the three inputs into provenance events. */
428→export function buildEvents({ snapshot, toolCallRows, captureEvents }) {
429→  const assets = snapshot?.assets ?? [];
430→  const poolSnapshotAt = snapshot?.pool_snapshot_at ?? "";
431→  const byId = new Map(assets.map((a) => [a.asset_id, a]));
432→
433→  const mentions = extractAssetMentions(captureEvents, assets);
434→
435→  // Service-side call records, grouped by normalised session key.
436→  const bridgeBySession = new Map();
437→  for (const row of toolCallRows) {
438→    if (row?.kind !== "bridge_call") continue;
439→    const status = Number(row.upstream_status ?? 0);
440→    const rejected = String(row.reject_reason ?? "").length > 0;
441→    const key = normalizeSessionKey(row.session_key);
442→    if (!bridgeBySession.has(key)) bridgeBySession.set(key, []);
443→    bridgeBySession.get(key).push({
444→      ok: !rejected && status >= 200 && status < 300,
445→      status,
446→      rejected,
447→      bridgeSource: String(row.bridge_source ?? ""),
448→      executedEndpoint: String(row.executed_endpoint ?? ""),
449→      requestBody: String(row.request_body ?? ""),
450→      actor: { user_id: String(row.user_id ?? ""), agent_id: String(row.agent_id ?? "") },
451→      teamId: String(row.team_id ?? ""),
452→      timestamp: String(row.timestamp ?? ""),
453→    });
454→  }
455→
456→  const events = [];
457→  const offeredNotRetrieved = [];
458→  const unpairedResponses = [];
459→
460→  for (const [assetId, sessions] of mentions) {
461→    const asset = byId.get(assetId);
462→    if (!asset) continue;
463→
464→    // Assets created after the pool was frozen are excluded: they leak answers.
465→    const staleAsset = Boolean(
466→      poolSnapshotAt && asset.asset_created_at && asset.asset_created_at > poolSnapshotAt,
467→    );
468→    const producer = { user_id: asset.producer_user_id, agent_id: asset.producer_agent_id };
469→
470→    for (const [sessionKey, bucket] of sessions) {
471→      const calls = bridgeBySession.get(sessionKey) ?? [];
472→      const targetedRows = calls.filter((c) => c.ok && callTargetsAsset(c, asset));
473→
474→      // Appearing in the capture is not retrieval. An id in a `skill/search`
475→      // response was offered; only a response to a command that asked for this
476→      // asset was retrieved. With no targeted response and no targeted row,
477→      // there is no fetch here — the asset did reach the model's context, and
478→      // that is `recalled` / `injected`, a different statement about a
479→      // different thing.
480→      if (bucket.responses.length === 0) {
481→        if (targetedRows.length === 0) {
482→          offeredNotRetrieved.push({
483→            asset_id: assetId, session_key: sessionKey, endpoints: [...bucket.endpoints],
484→          });
485→        }
486→        continue;
487→      }
488→
489→      // Pair each response with the service row for the same request, matched
490→      // on the request payload — and only when the pairing is forced.
491→      //
492→      // Two identical requests with one surviving row have no answer: nothing
493→      // distinguishes the requests, so nothing says which response lost its
494→      // record. Taking them in order picks one arbitrarily, and the cost of
495→      // being wrong is not symmetric — one event gets evidence from a call it
496→      // never made, and the other is reported as a telemetry gap. Both
497→      // statements are false and the second one hides the first.
498→      //
499→      // So a group pairs only when the counts match. Otherwise every response
500→      // in it stays wire_only, the rows stay unattached, and the ambiguity is
501→      // reported. Warning while still binding would be the worst of both: the
502→      // wrong link is made and the note explaining why it might be wrong sits
503→      // somewhere else entirely.
504→      const rowsByPayload = new Map();
505→      for (const r of targetedRows) {
506→        const key = canonicalRequest(r.requestBody);
507→        if (!rowsByPayload.has(key)) rowsByPayload.set(key, []);
508→        rowsByPayload.get(key).push(r);
509→      }
510→      for (const rows of rowsByPayload.values()) {
511→        rows.sort((a, b) => String(a.timestamp).localeCompare(String(b.timestamp)));
512→      }
513→
514→      const responsesByPayload = new Map();
515→      for (const r of bucket.responses) {
516→        if (!responsesByPayload.has(r.requestPayload)) responsesByPayload.set(r.requestPayload, []);
517→        responsesByPayload.get(r.requestPayload).push(r);
518→      }
519→
520→      // Only groups whose counts match may pair. Within such a group both
521→      // sides are in the order the calls were made, so position is sound.
522→      const pairable = new Map();
523→      for (const [payload, responses] of responsesByPayload) {
524→        const rows = rowsByPayload.get(payload) ?? [];
525→        if (rows.length === responses.length && rows.length > 0) {
526→          pairable.set(payload, [...rows]);
527→          continue;
528→        }
529→        unpairedResponses.push({
530→          asset_id: assetId,
531→          session_key: sessionKey,
532→          responses: responses.length,
533→          service_rows: rows.length,
534→          note: rows.length === 0
535→            ? "no service row carries this request"
536→            : "identical requests, unequal counts: which response lost its row cannot be decided, "
537→              + "so none of them is paired and the row is left unattached",
538→        });
539→      }
540→
541→      const rowFor = (response) => {
542→        const rows = pairable.get(response.requestPayload);
543→        return rows && rows.length > 0 ? rows.shift() : null;
544→      };
545→
546→      for (const response of bucket.responses) {
547→        const row = rowFor(response);
548→        // A refused call is an attempt, not a fetch: the acceptance and the
549→        // service rows keep the attempt; no fetched event is written for it.
550→        if (response.refused != null) continue;
551→        const actor = row?.actor ?? calls[0]?.actor ?? { user_id: "", agent_id: "" };
552→        const observation = row ? "bridge+wire" : "wire_only";
553→
554→        const proofRefs = [];
555→        if (row) {
556→          proofRefs.push({
557→            kind: "bridge_row",
558→            ref: `tool_call_logs:${row.timestamp}:${row.bridgeSource}:${row.executedEndpoint}`,
559→            detail: `request names ${assetId}`,
560→          });
561→        }
562→        proofRefs.push({
563→          kind: "capture_line",
564→          ref: `${sessionKey}:${response.callId || `msg[${response.messageIndex}]`}`,
565→          detail: [
566→            `${response.endpoint || "a targeted call"} answered at message ${response.messageIndex}`,
567→            response.delivered === true ? "carrying content" : response.delivered === false ? "carrying no content" : "content undetermined",
568→            response.version == null ? "version not stated" : `version ${response.version}`,
569→            row ? "" : "no service-side row recorded it — telemetry gap",
570→          ].filter(Boolean).join("; "),
571→        });
572→
573→        events.push({
574→          schema_version: "provenance-v1",
575→          event_id: eventId([sessionKey, assetId, "fetched", response.callId, String(response.messageIndex), observation]),
576→          state: "fetched",
577→          session_key: sessionKey,
578→          run_id: null,
579→          task_id: null,
580→          occurred_at: row?.timestamp ?? null,
581→          asset_id: assetId,
582→          asset_type: asset.asset_type,
583→          asset_name: asset.name,
584→          // Every one of the next three comes from this same response. Taking
585→          // them from whichever response happened to have each one is how a
586→          // record gets assembled that describes a retrieval nobody made.
587→          asset_version: response.version ?? null,
588→          asset_created_at: asset.asset_created_at ?? "",
589→          pool_snapshot_at: poolSnapshotAt,
590→          excluded_by_snapshot: staleAsset,
591→          producer_user_id: producer.user_id,
592→          producer_agent_id: producer.agent_id,
593→          actor_user_id: actor.user_id,
594→          actor_agent_id: actor.agent_id,
595→          relation: classifyRelation(producer, actor),
596→          observation,
597→          content_delivered: response.delivered,
598→          context_entry_index: response.delivered === true ? response.messageIndex : null,
599→          evidence_tier: null,
600→          bridge_source: row?.bridgeSource ?? "",
601→          executed_endpoint: row?.executedEndpoint ?? response.endpoint ?? "",
602→          upstream_status: row?.status ?? 0,
603→          target_type: null,
604→          target_ref: null,
605→          proof_refs: proofRefs,
606→          corrected_reason: null,
607→          parent_event_ids: [],
608→        });
609→      }
610→    }
611→  }
612→
613→  // Channels with a service-side success the capture never saw get their own
614→  // record. Dropping them would suggest the call never happened — a gap in
615→  // collection and an absence of activity are not the same thing.
616→  const seenPairs = new Set(events.map((e) => `${e.session_key}|${e.asset_id}`));
617→  for (const [sessionKey, calls] of bridgeBySession) {
618→    for (const call of calls.filter((c) => c.ok)) {
619→      // A row that names an asset is attributed to it, even with no capture.
620→      const named = assets.find((a) => callTargetsAsset(call, a));
621→      if (named && seenPairs.has(`${sessionKey}|${named.asset_id}`)) continue;
622→      if (!named && [...seenPairs].some((k) => k.startsWith(`${sessionKey}|`))) continue;
623→
624→      const producer = named
625→        ? { user_id: named.producer_user_id, agent_id: named.producer_agent_id }
626→        : { user_id: "", agent_id: "" };
627→
628→      events.push({
629→        schema_version: "provenance-v1",
630→        event_id: eventId([sessionKey, named?.asset_id ?? "", "fetched", call.timestamp, "bridge_only", call.bridgeSource, call.executedEndpoint]),
631→        state: "fetched",
632→        session_key: sessionKey,
633→        run_id: null,
634→        task_id: null,
635→        occurred_at: call.timestamp || null,
636→        asset_id: named?.asset_id ?? "",
637→        asset_type: named?.asset_type ?? "",
638→        asset_name: named?.name ?? "",
639→        // Only the snapshot knows a version here, and the snapshot is not
640→        // entitled to say which revision a call returned.
641→        asset_version: null,
642→        asset_created_at: named?.asset_created_at ?? "",
643→        pool_snapshot_at: poolSnapshotAt,
644→        excluded_by_snapshot: false,
645→        producer_user_id: producer.user_id,
646→        producer_agent_id: producer.agent_id,
647→        actor_user_id: call.actor.user_id,
648→        actor_agent_id: call.actor.agent_id,
649→        relation: named ? classifyRelation(producer, call.actor) : "unknown",
650→        observation: "bridge_only",
651→        // The response was never captured. Unknown, which is not false — and
652→        // not something a later stage may promote on either.
653→        content_delivered: null,
654→        context_entry_index: null,
655→        evidence_tier: null,
656→        bridge_source: call.bridgeSource,
657→        executed_endpoint: call.executedEndpoint,
658→        upstream_status: call.status,
659→        target_type: null,
660→        target_ref: null,
661→        proof_refs: [{
662→          kind: "bridge_row",
663→          ref: `tool_call_logs:${call.timestamp}:${call.bridgeSource}:${call.executedEndpoint}`,
664→          detail: named ? `request names ${named.asset_id}; the capture never saw the response` : "the capture never saw this call",
665→        }],
666→        corrected_reason: null,
667→        parent_event_ids: [],
668→      });
669→      if (named) seenPairs.add(`${sessionKey}|${named.asset_id}`);
670→    }
671→  }
672→
673→  events.offeredNotRetrieved = offeredNotRetrieved;
674→  events.unpairedResponses = unpairedResponses;
675→  events.unknownAssets = mentions.unknownAssets ?? [];
676→  return events;
677→}
