49→export function outcomeOfAttempt(resultText) {
50→  const { output } = splitCommandAndOutput(resultText);
51→  const s = String(resultText ?? "");
52→  const exit = /(?:^|\n)Exit code:\s*(\d+)/.exec(s);
53→  const exitCode = exit ? Number(exit[1]) : null;
54→  if (exitCode === 28 || /Operation timed out|Connection timed out/.test(s)) return { ok: false, why: "timed out" };
55→  if (exitCode !== null && exitCode !== 0) return { ok: false, why: `exit ${exitCode}` };
56→  if (/Could not resolve host|Connection refused|Failed to connect/.test(s)) return { ok: false, why: "could not connect" };
57→  const http = /HTTP_CODE:\s*(\d{3})/.exec(s);
58→  if (http && !/^2/.test(http[1])) return { ok: false, why: `http ${http[1]}` };
59→  const envelope = /"code"\s*:\s*(\d+)/.exec(output);
60→  if (envelope) {
61→    if (Number(envelope[1]) !== 0) return { ok: false, why: `service code ${envelope[1]}` };
62→    const marker = CHECKLIST_MARKER.exec(output);
63→    return marker
64→      ? { ok: true, why: `code 0, marker ${marker[1]}` }
65→      : { ok: false, why: "code 0 but the content carries no checklist-marker" };
66→  }
67→  if (!output.trim()) return { ok: null, why: "no output" };
68→  return { ok: null, why: "outcome not readable" };
69→}
