  1→/**
  2→ * Provenance event builder — puts "who wrote it" and "who used it" on one record.
  3→ *
  4→ * The existing telemetry is missing that edge. `tool_call_logs` records only the
  5→ * consumer (user_id / agent_id); the asset's owner lives in the asset record, and
  6→ * the two were never joined. Without the edge neither the team dimension nor
  7→ * author confidence can be computed — and it cannot be backfilled later, because
  8→ * asset ownership changes and versions roll forward, so a lookup after the fact
  9→ * returns a different row than the one that was actually used.
 10→ *
 11→ * Each of the three inputs answers only part of the question:
 12→ *
 13→ *   asset pool snapshot   who wrote it, when, which version
 14→ *   tool_call_logs        who used it, whether the call succeeded
 15→ *                         (written by the service itself; the model cannot alter it)
 16→ *   capture JSONL         which asset ids came back in the response
 17→ *
 18→ * That last one is the crux: a `skill/search` bridge row records the request only,
 19→ * so it holds the query but not what was returned. Asset identity can therefore be
 20→ * recovered only from the captured response. Each event records how the fetch was
 21→ * witnessed in `observation`:
 22→ *
 23→ *   bridge+wire   service-side success record AND an asset id parsed from the
 24→ *                 capture (strongest)
 25→ *   bridge_only   service-side success, but the capture missed it — only the
 26→ *                 channel is known
 27→ *   wire_only     an asset id in the capture with no matching service-side
 28→ *                 success record (doubtful)
 29→ *
 30→ * Usage:
 31→ *   node evaluation/provenance/build-events.mjs \
 32→ *     evaluation/provenance/artifacts/asset-pool-snapshot.json \
 33→ *     evaluation/gate0/artifacts/tool-call-logs.jsonl \
 34→ *     [capture.jsonl ...]
 35→ */
 36→
 37→import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
 38→import { createHash } from "node:crypto";
 39→import { dirname } from "node:path";
 40→
 41→/**
 42→ * Stable event id, referenced by gate decisions (`evidence_refs`) and receipts.
 43→ * Derived from content rather than generated randomly, so re-running over the
 44→ * same input yields the same ids and the two sides can be reconciled.
 45→ */
 46→export function eventId(parts) {
 47→  const digest = createHash("sha1").update(parts.join("|")).digest("hex");
 48→  return `evt-${digest.slice(0, 12)}`;
 49→}
 50→
 51→/** Relation between consumer and producer. Only cross_user is team value. */
 52→export function classifyRelation(producer, actor) {
 53→  const pu = producer.user_id || "";
 54→  const pa = producer.agent_id || "";
 55→  const au = actor.user_id || "";
 56→  const aa = actor.agent_id || "";
 57→
 58→  // If either identity is missing the relation is undecidable. Report unknown
 59→  // rather than defaulting to self — defaulting would quietly erase genuine
 60→  // cross-person use.
 61→  if (!pu || !au) return "unknown";
 62→  if (pu !== au) return "cross_user";
 63→  if (pa && aa && pa !== aa) return "cross_agent";
 64→  return "self";
 65→}
 66→
 67→/**
 68→ * The proxy prefixes session_key with the client name (codebuddy:xxx) while the
 69→ * knowledge service stores the bare x-conversation-id. Normalise before joining.
 70→ */
 71→export function normalizeSessionKey(key) {
 72→  const s = String(key ?? "");
 73→  const idx = s.indexOf(":");
 74→  return idx >= 0 ? s.slice(idx + 1) : s;
 75→}
 76→
 77→/** Parse JSONL line by line, skipping malformed lines instead of failing whole. */
 78→export function parseJsonl(text) {
 79→  const rows = [];
 80→  for (const line of String(text).split("\n")) {
 81→    if (!line.trim()) continue;
 82→    try { rows.push(JSON.parse(line)); } catch { /* skip malformed line */ }
 83→  }
 84→  return rows;
 85→}
 86→
 87→/**
 88→ * Split a Bash tool result into the command that was issued and the output it
 89→ * produced.
 90→ *
 91→ * These must never be scanned as one blob. A tool result echoes the command
 92→ * before its output, so a call that timed out after 75 s with empty stdout
 93→ * still contains the bridge URL and the asset name — matching the whole thing
 94→ * reads the *request* as if it were the response. The endpoint is read from the
 95→ * command, which is what the command is for; the payload only from the output.
 96→ */
 97→export function splitCommandAndOutput(text) {
 98→  const s = String(text ?? "");
 99→  const i = s.search(/(^|\n)Stdout:/);
100→  // No envelope — a native tool result rather than a shell call. The two halves
101→  // cannot be separated, so the whole thing is treated as output and the
102→  // command as absent. That keeps the id visible while making targeting
103→  // undecidable, which is the honest reading: with no command to inspect,
104→  // nothing here can establish that this asset was the one asked for.
105→  if (i < 0) return { command: "", output: s };
106→  const nl = s.indexOf("Stdout:", i);
107→  return { command: s.slice(0, i), output: s.slice(nl + "Stdout:".length) };
108→}
109→
110→/**
111→ * The action a command invoked, as `skill:search`, or "" if not one.
112→ *
113→ * The knowledge service is not shaped like the other two. It runs on its own
114→ * port and takes the operation in the body (`tool_name`) rather than in the
115→ * path, so a path-only pattern does not see it at all — and an unrecognised
116→ * command means the response is never inspected, which shows up as "delivery
117→ * unknown" for a channel where delivery is perfectly knowable.
118→ */
119→export function commandEndpoint(command) {
120→  const cmd = String(command ?? "");
121→  const bridge = /https?:\/\/[^\s'"]*\/(skill|memory)-bridge\/v3\/[a-z]+\/([a-z/-]+)/.exec(cmd);
122→  if (bridge) return `${bridge[1]}:${bridge[2].replace(/\/+$/, "")}`;
123→
124→  if (/https?:\/\/[^\s'"]*\/v3\/tools\/call/.test(cmd)) {
125→    const tool = /"tool_name"\s*:\s*"([^"]+)"/.exec(cmd);
126→    return `knowledge:${tool ? tool[1] : "call"}`;
127→  }
128→  if (/https?:\/\/[^\s'"]*\/v3\/tools\/list/.test(cmd)) return "knowledge:list";
129→  return "";
130→}
131→
132→/** Enumeration endpoints hand back a list; they never retrieve one asset. */
133→export function isListingAction(action) {
134→  return /^(search|list|listing|list_[a-z_]+|search_[a-z_]+)$/.test(String(action ?? "").split(":").pop() ?? "");
135→}
136→
137→/**
138→ * Did this command ask for *this* asset's content?
139→ *
140→ * The distinction that the whole `fetched` state rests on: appearing in a
141→ * `skill/search` result means the asset was **offered**, and appearing in a
142→ * `get-by-name` response means it was **retrieved**. Only the second is a fetch.
143→ */
144→export function commandTargetsAsset(command, asset) {
145→  const cmd = String(command ?? "");
146→  const endpoint = commandEndpoint(cmd);
147→  if (!endpoint || isListingAction(endpoint)) return false;
148→  const id = String(asset?.asset_id ?? "");
149→  const name = String(asset?.name ?? "");
150→  if (id && cmd.includes(id)) return true;
151→  if (name && new RegExp(`"(name|skill_name)"\\s*:\\s*"${escapeRegExp(name)}"`).test(cmd)) return true;
152→  return false;
153→}
154→
155→/**
156→ * What a bridge response actually handed back for this asset.
157→ *
158→ * A non-enumeration endpoint is not enough to say the body arrived. `get` with
159→ * `include_content:false` answers with id, name and version; `update` answers
160→ * with a metadata summary. Both name the asset, both come from an endpoint that
161→ * is not a listing, and neither delivers a single line of the asset's content —
162→ * so an endpoint allow-list would pass all of them.
163→ *
164→ * The version is read from the same place for the same reason: the response
165→ * states which revision it returned, and that is the only source entitled to
166→ * say so. The snapshot's version describes the pool now, not what came back.
167→ *
168→ * Returns `{ delivered, version }` where `delivered` is null when the payload
169→ * could not be parsed at all — unknown, which is not false.
170→ */
171→export function inspectDelivery(output, assetId) {
172→  const envelope = firstJsonObject(output);
173→  if (!envelope) return { delivered: null, version: null };
174→
175→  // An explicit refusal — the envelope's own non-zero code (40301 not
176→  // visible, 40401 not found, 40302 write disabled …) — is a known
177→  // non-delivery, not an unknown one. Nothing of the asset came back, and a
178→  // later stage must not read "fetched" into it (found on the second
179→  // scenario's first preparation run, where every get was refused and the
180→  // receipt would have said 已取回).
181→  if (typeof envelope.code === "number" && envelope.code !== 0) {
182→    return { delivered: false, version: null, refused: envelope.code };
183→  }
184→
185→  // The asset may be the whole payload or one item inside a list.
186→  const data = envelope.data ?? envelope;
187→  const candidates = [data, ...(Array.isArray(data?.items) ? data.items : [])];
188→  const record = candidates.find((c) => c && typeof c === "object"
189→    && [c.skill_id, c.wiki_id, c.asset_id, c.id].some((v) => String(v ?? "") === assetId));
190→  if (!record) return { delivered: null, version: null };
191→
192→  const body = [record.content, record.skill_md, record.body, record.text, record.markdown]
193→    .find((v) => typeof v === "string");
194→  const version = record.version ?? null;
195→
196→  // A field that exists but is empty is a delivery of nothing. The threshold is
197→  // deliberately low — one line of real content is content — but zero is zero.
198→  return { delivered: typeof body === "string" ? body.trim().length > 0 : false, version };
199→}
200→
201→/** First balanced JSON object in a blob of text. */
202→function firstJsonObject(text) {
203→  const s = String(text ?? "");
204→  const start = s.indexOf("{");
205→  if (start < 0) return null;
206→  let depth = 0, inStr = false, esc = false;
207→  for (let i = start; i < s.length; i += 1) {
208→    const ch = s[i];
209→    if (inStr) {
210→      if (esc) esc = false;
211→      else if (ch === "\\") esc = true;
212→      else if (ch === '"') inStr = false;
213→      continue;
214→    }
215→    if (ch === '"') inStr = true;
216→    else if (ch === "{") depth += 1;
217→    else if (ch === "}") {
218→      depth -= 1;
219→      if (depth === 0) { try { return JSON.parse(s.slice(start, i + 1)); } catch { return null; } }
220→    }
221→  }
222→  return null;
223→}
224→
225→/** Every tool result in a captured request, paired with its call id. */
226→function toolResultsOf(body) {
227→  const out = [];
228→  const msgs = Array.isArray(body?.messages) ? body.messages : [];
229→  msgs.forEach((message, index) => {
230→    if (message?.role === "tool") {
231→      const c = message.content;
232→      out.push({ index, callId: String(message.tool_call_id ?? ""), text: typeof c === "string" ? c : JSON.stringify(c ?? "") });
233→    }
234→    const blocks = Array.isArray(message?.content) ? message.content : [];
235→    for (const block of blocks) {
236→      if (block?.type !== "tool_result") continue;
237→      const c = block.content;
238→      out.push({ index, callId: String(block.tool_use_id ?? ""), text: typeof c === "string" ? c : JSON.stringify(c ?? "") });
239→    }
240→  });
241→  return out;
242→}
243→
244→/** Canonical form of a JSON blob, so two spellings of one body compare equal. */
245→/**
246→ * Keys the proxy adds to a request body on the way through. The model never
247→ * writes these; the bridge injects identity from the session (skill-bridge.ts:
248→ * user_id / team_id / agent_id, plus routing fields). So the service-side
249→ * `request_body` is the model's body *plus* these, and an exact-string compare
250→ * against what the model wrote never matches. That is what left A's two
251→ * get-by-name calls reporting wire_only with "no service row" when the rows
252→ * were right there.
253→ */
254→const PROXY_INJECTED_KEYS = new Set([
255→  "user_id", "team_id", "agent_id", "task_id", "space_id", "service_id",
256→]);
257→
258→/**
259→ * Canonical form of a request body for matching: parsed, keys sorted at every
260→ * depth, and the proxy-injected identity fields dropped from the top level.
261→ *
262→ * Dropping them is a defined normalisation, not a loosening — the fields that
263→ * distinguish one call from another (skill_id, skill_name, include_content)
264→ * are all kept, so two different requests still differ. Within one session the
265→ * identity is constant, so removing it cannot merge calls that were really
266→ * distinct.
267→ */
268→function canonicalRequest(text) {
269→  let obj;
270→  try { obj = JSON.parse(String(text ?? "")); } catch { return String(text ?? "").trim(); }
271→  const sort = (v) => {
272→    if (Array.isArray(v)) return v.map(sort);
273→    if (v && typeof v === "object") {
274→      const out = {};
275→      for (const k of Object.keys(v).sort()) out[k] = sort(v[k]);
276→      return out;
277→    }
278→    return v;
279→  };
280→  if (obj && typeof obj === "object" && !Array.isArray(obj)) {
281→    const kept = {};
282→    for (const k of Object.keys(obj)) if (!PROXY_INJECTED_KEYS.has(k)) kept[k] = obj[k];
283→    obj = kept;
284→  }
285→  return JSON.stringify(sort(obj));
286→}
287→
288→/** The `-d '…'` payload a curl command carried, for pairing with a service row. */
289→export function requestPayloadOf(command) {
290→  const m = /-d\s+'([\s\S]*?)'(?:\s|$)/.exec(String(command ?? ""))
291→    ?? /-d\s+"([\s\S]*?)"(?:\s|$)/.exec(String(command ?? ""));
292→  if (!m) return "";
293→  return canonicalRequest(m[1]);
294→}
295→
296→/**
297→ * Where each asset was seen in the capture, and — the part that matters —
298→ * whether the call that produced it had asked for that asset.
299→ *
300→ * Every targeted response is kept **separately**. Summarising them per asset
301→ * per session is what produced events assembled from different calls: a first
302→ * `get` with include_content:false supplying the version, a second `get` of a
303→ * different revision supplying the delivery flag and the entry position, and
304→ * the first call id supplying the evidence reference. Every field passed its
305→ * own check and the record as a whole described a retrieval that never
306→ * happened — and it validated against the contract, because the contract
307→ * constrains fields, not their provenance.
308→ *
309→ * So version, delivery, position and reference all come from one response, and
310→ * an asset read twice produces two events.
311→ *
312→ * Only tool *results* are searched: a request carries intent rather than
313→ * delivery. Within a result, the asset id must appear in the output half and
314→ * the targeting decision is made from the command half.
315→ */
316→export function extractAssetMentions(events, assets) {
317→  const mentions = new Map(); // assetId -> Map<sessionKey, {targeted, endpoints:Set, callIds:Set}>
318→  const list = [...assets].filter((a) => a?.asset_id);
319→  if (list.length === 0) return mentions;
320→  const known = new Set(list.map((a) => a.asset_id));
321→  // Targeted responses for assets the frozen snapshot does not hold. Iterating
322→  // the snapshot's assets makes these invisible, and invisible is the worst
323→  // outcome for exactly this case: an asset that appeared after the freeze —
324→  // the system auto-extracts skills from finished sessions — is the answer
325→  // leak the freeze exists to catch. The first real consumer run read such a
326→  // skill before any credited asset and no event recorded it.
327→  const unknown = new Map(); // asset_id -> {asset_id, name, version, sessions:Set, first_index}
328→
329→  for (const event of events) {
330→    if (event?.event !== "http.request") continue;
331→    const body = event?.body?.json;
332→    if (!body || !Array.isArray(body.messages)) continue;
333→
334→    const sessionKey = normalizeSessionKey(
335→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
336→    );
337→
338→    for (const { index, callId, text } of toolResultsOf(body)) {
339→      const { command, output } = splitCommandAndOutput(text);
340→      if (!output) continue;
341→
342→      // A non-listing response naming a skill id the snapshot lacks.
343→      const ep = commandEndpoint(command);
344→      if (ep && !isListingAction(ep)) {
345→        const env = firstJsonObject(output);
346→        const rec = env?.data && typeof env.data === "object" ? env.data : null;
347→        const rid = rec ? String(rec.skill_id ?? rec.wiki_id ?? rec.asset_id ?? "") : "";
348→        if (rid && !known.has(rid)) {
349→          if (!unknown.has(rid)) {
350→            unknown.set(rid, { asset_id: rid, name: String(rec.name ?? ""), version: rec.version ?? null, sessions: new Set(), first_index: index });
351→          }
352→          const u = unknown.get(rid);
353→          u.sessions.add(sessionKey);
354→          if (index < u.first_index) u.first_index = index;
355→        }
356→      }
357→
358→      for (const asset of list) {
359→        if (!output.includes(asset.asset_id)) continue;
360→        if (!mentions.has(asset.asset_id)) mentions.set(asset.asset_id, new Map());
361→        const bySession = mentions.get(asset.asset_id);
362→        if (!bySession.has(sessionKey)) {
363→          bySession.set(sessionKey, {
364→            endpoints: new Set(), offered: false, responses: [], seen: new Set(),
365→          });
366→        }
367→        const bucket = bySession.get(sessionKey);
368→        const endpoint = commandEndpoint(command);
369→        if (endpoint) bucket.endpoints.add(endpoint);
370→
371→        if (!commandTargetsAsset(command, asset)) { bucket.offered = true; continue; }
372→
373→        // Results repeat as the conversation grows; record each response once.
374→        const key = `${callId}|${index}`;
375→        if (bucket.seen.has(key)) continue;
376→        bucket.seen.add(key);
377→
378→        // One response, one record. The index is the message carrying the
379→        // *result*, not the call: a model can emit several calls in one
380→        // message, and the second was written before the first one's result
381→        // existed.
382→        const { delivered, version, refused = null } = inspectDelivery(output, asset.asset_id);
383→        bucket.responses.push({
384→          callId, endpoint, messageIndex: index, delivered, version, refused,
385→          requestPayload: requestPayloadOf(command),
386→        });
387→      }
388→    }
389→  }
390→  mentions.unknownAssets = [...unknown.values()].map((u) => ({ ...u, sessions: [...u.sessions] }));
391→  return mentions;
392→}
