772→  const [snapshotPath, toolCallPath, ...capturePaths] = process.argv.slice(2);
773→  if (!snapshotPath || !toolCallPath) {
774→    console.error("usage: node build-events.mjs <snapshot.json> <tool-call-logs.jsonl> [capture.jsonl ...]");
