 23→  team_id: "team-eval",
 24→  assets: [{
 25→    asset_id: "skl-wrong", asset_type: "skill", name: "eval-bridge-endpoint-a",
 26→    producer_user_id: "usr-author", producer_agent_id: "agt-author",
 27→    version: 9, asset_created_at: "2026-08-20T00:00:00Z",
 28→  }],
 29→};
 30→
 31→const GET = "http://127.0.0.1:8096/skill-bridge/v3/skill/get";
 32→const TOKENS_V1 = { "skl-wrong": { version: 1, tokens: ["10.244.7.19"] } };
 33→
 34→const row = (over) => ({
 35→  kind: "bridge_call", session_key: "codebuddy:conv-1",
 36→  user_id: "usr-consumer", agent_id: "agt-consumer",
 37→  bridge_source: "skill-bridge", executed_endpoint: "get",
 38→  upstream_status: 200, reject_reason: "", ...over,
 39→});
 40→
 41→const call = (id) => ({ role: "assistant", tool_calls: [{ id, function: { name: "Bash", arguments: "{}" } }] });
 42→const result = (id, body, stdout) => ({
 43→  role: "tool", tool_call_id: id,
 44→  content: `Command: curl -X POST ${GET} -d '${body}'\nStdout: ${stdout}`,
 45→});
