 51→function capture(messages) {
 52→  return [{
 53→    event: "http.request",
 54→    requestId: "req-1",
 55→    timestamp: "2026-09-04T13:30:00Z",
 56→    headers: { "x-conversation-id": "conv-1" },
 57→    body: { json: { messages } },
 58→  }];
 59→}
