 71→test("a metadata-only read of v1 cannot lend its version to a content read of v2", () => {
 72→  // The reported reproduction, end to end. Read v1 with the body switched off,
 73→  // read v2 with the body on, then use a token that exists only in v1. The
 74→  // answer must be needs_review: v1's content never arrived.
 75→  const judged = runChain(
 76→    [
