595→/** Parse a JSONL file, skipping unparsable lines. */
596→export function parseCapture(text) {
597→  return text
598→    .split("\n")
599→    .filter((line) => line.trim().length > 0)
600→    .flatMap((line) => {
601→      try {
602→        return [JSON.parse(line)];
603→      } catch {
604→        return [];
605→      }
606→    });
607→}
